effect.shader:
void main(){
    float a=radians(viewAngle);
    vec2 vdir=vec2(cos(a),sin(a))*depth*0.08;
    vec2 uv=acScreenNorm;
    for(int i=0;i<16;i++){
        float h=dot(texture2DCv(inputImg.texture, uv).rgb, vec3(0.333));
        uv += vdir*(h-0.5)/16.0;
    }
    gl_FragColor=texture2DCv(inputImg.texture, uv);
}
